19	package org.apache.hadoop.yarn.server.resourcemanager.scheduler.capacity;
20	
21	import java.util.Arrays;
22	import java.util.Iterator;
23	import java.util.NoSuchElementException;
24	import java.util.Objects;
25	
26	import static org.apache.hadoop.yarn.server.resourcemanager.scheduler.capacity.CapacitySchedulerConfiguration.DOT;
27	import static org.apache.hadoop.yarn.server.resourcemanager.scheduler.capacity.CapacitySchedulerConfiguration.ROOT;
28	
29	/**
30	 * This is a helper class which represents a queue path, and has easy access
31	 * methods to get the path's parent or leaf part, or as a whole.
32	 */
33	public class QueuePath implements Iterable<String> {
34	  private static final String QUEUE_REGEX_DELIMITER = "\\.";
35	  /**
36	   * The parent part of the queue path.
37	   */
38	  private String parent;
39	
40	  /**
41	   * The leaf part of the parent path.
42	   */
43	  private String leaf;
44	
45	  /**
46	   * Constructor to create mapping queue path from parent path and leaf name.
47	   * @param parent Parent path of the queue
48	   * @param leaf Name of the leaf queue
49	   */
50	  public QueuePath(String parent, String leaf) {
51	    this.parent = parent;
52	    this.leaf = leaf;
53	  }
54	
55	  /**
56	   * Constructor creates a MappingQueuePath object using the queue's full path.
57	   * @param fullPath Full path of the queue
58	   */
59	  public QueuePath(String fullPath) {
60	    setFromFullPath(fullPath);
61	  }
62	
63	  /**
64	   * Constructor to create Queue path from queue names.
65	   * The provided queue names will be concatenated by dots, giving a full
66	   * queue path.
67	   * @param parts Parts of queue path
68	   * @return QueuePath object
69	   */
70	  public static QueuePath createFromQueues(String... parts) {
71	    return new QueuePath(String.join(DOT, parts));
72	  }
73	
74	  /**
75	   * This method is responsible for splitting up a full queue path into parent
76	   * path and leaf name.
77	   * @param fullPath Full path of the queue to be processed
78	   */
79	  private void setFromFullPath(String fullPath) {
80	    parent = null;
81	    leaf = fullPath;
82	
83	    if (leaf == null) {
84	      leaf = "";
85	      return;
86	    }
87	
88	    int lastDotIdx = fullPath.lastIndexOf(DOT);
89	    if (lastDotIdx > -1) {
90	      parent = fullPath.substring(0, lastDotIdx).trim();
91	      leaf = fullPath.substring(lastDotIdx + 1).trim();
92	    }
93	  }
94	
95	  /**
96	   * Simple helper method to determine if the path contains any empty parts.
97	   * @return true if there is at least one empty part of the path
98	   */
99	  public boolean hasEmptyPart() {
100	    for (String part : this) {
101	      if (part.isEmpty()) {
102	        return true;
103	      }
104	    }
105	
106	    return false;
107	  }
108	
109	  /**
110	   * Getter for the parent part of the path.
111	   * @return Parent path of the queue, null if there is no parent.
112	   */
113	  public String getParent() {
114	    return parent;
115	  }
116	
117	  /**
118	   * Getter for the leaf part of the path.
119	   * @return The leaf queue name
120	   */
121	  public String getLeafName() {
122	    return leaf;
123	  }
124	
125	  /**
126	   * Getter for the full path of the queue.
127	   * @return Full path of the queue
128	   */
129	  public String getFullPath() {
130	    return hasParent() ? (parent + DOT + leaf) : leaf;
131	  }
132	
133	  /**
134	   * Convenience getter to check if the queue has a parent path defined.
135	   * @return True if there is a parent path provided
136	   */
137	  public boolean hasParent() {
138	    return parent != null;
139	  }
140	
141	  /**
142	   * Convenience getter to check if the queue is the root queue.
143	   * @return True if the path is root
144	   */
145	  public boolean isRoot() {
146	    return !hasParent() && leaf.equals(ROOT);
147	  }
148	
149	  /**
150	   * Creates a new {@code QueuePath} from the current full path as parent, and
151	   * the appended child queue path as leaf.
152	   * @param childQueue path of leaf queue
153	   * @return new queue path made of current full path and appended leaf path
154	   */
155	  public QueuePath createNewLeaf(String childQueue) {
156	    return new QueuePath(getFullPath(), childQueue);
157	  }
158	
159	  /**
160	   * Returns an iterator of queue path parts, starting from the highest level
161	   * (generally root).
162	   * @return queue part iterator
163	   */
164	  @Override
165	  public Iterator<String> iterator() {
166	    return Arrays.asList(getFullPath().split(QUEUE_REGEX_DELIMITER)).iterator();
167	  }
168	
169	  /**
170	   * Returns an iterator that provides a way to traverse the queue path from
171	   * current queue through its parents.
172	   * @return queue path iterator
173	   */
174	  public Iterator<String> reverseIterator() {
175	
176	    return new Iterator<String>() {
177	      private String current = getFullPath();
178	
179	      @Override
180	      public boolean hasNext() {
181	        return current != null;
182	      }
183	
184	      @Override
185	      public String next() {
186	        if (!hasNext()) {
187	          throw new NoSuchElementException();
188	        }
189	
190	        int parentQueueNameEndIndex = current.lastIndexOf(".");
191	        String old = current;
192	        if (parentQueueNameEndIndex > -1) {
193	          current = current.substring(0, parentQueueNameEndIndex).trim();
194	        } else {
195	          current = null;
196	        }
197	
198	        return old;
199	      }
200	    };
201	  }
202	
203	  @Override
204	  public String toString() {
205	    return getFullPath();
206	  }
207	
208	  @Override
209	  public boolean equals(Object o) {
210	    if (this == o) {
211	      return true;
212	    }
213	    if (o == null || getClass() != o.getClass()) {
214	      return false;
215	    }
216	    QueuePath other = (QueuePath) o;
217	    return Objects.equals(parent, other.parent) &&
218	        Objects.equals(leaf, other.leaf);
219	  }
220	
221	  @Override
222	  public int hashCode() {
223	    return Objects.hash(parent, leaf);
224	  }
225	}
