332	  protected void setupQueueConfigs(Resource clusterResource) throws
333	      IOException {
334	
335	    writeLock.lock();
336	    try {
337	      CapacitySchedulerConfiguration configuration = queueContext.getConfiguration();
338	      if (isDynamicQueue() || this instanceof AbstractAutoCreatedLeafQueue) {
339	        setDynamicQueueProperties();
340	      }
341	
342	      // Collect and set the Node label configuration
343	      this.queueNodeLabelsSettings = new QueueNodeLabelsSettings(configuration, parent,
344	          getQueuePath(), queueContext.getQueueManager().getConfiguredNodeLabelsForAllQueues());
345	
346	      // Initialize the queue capacities
347	      setupConfigurableCapacities();
348	      updateAbsoluteCapacities();
349	      updateCapacityConfigType();
350	
351	      // Fetch minimum/maximum resource limits for this queue if
352	      // configured
353	      updateConfigurableResourceLimits(clusterResource);
354	
355	      // Setup queue's maximumAllocation respecting the global
356	      // and the queue settings
357	      this.queueAllocationSettings.setupMaximumAllocation(configuration, getQueuePath(),
358	          parent);
359	
360	      // Initialize the queue state based on previous state, configured state
361	      // and its parent state
362	      initializeQueueState();
363	
364	      authorizer = YarnAuthorizationProvider.getInstance(configuration);
365	
366	      this.acls = configuration.getAcls(getQueuePath());
367	
368	      this.userWeights = getUserWeightsFromHierarchy();
369	
370	      this.reservationsContinueLooking =
371	          configuration.getReservationContinueLook();
372	
373	      this.configuredCapacityVectors = configuration
374	          .parseConfiguredResourceVector(queuePath.getFullPath(),
375	              this.queueNodeLabelsSettings.getConfiguredNodeLabels());
376	
377	      // Update metrics
378	      CSQueueUtils.updateQueueStatistics(resourceCalculator, clusterResource,
379	          this, labelManager, null);
380	
381	      // Store preemption settings
382	      this.preemptionSettings = new CSQueuePreemptionSettings(this, configuration);
383	      this.priority = configuration.getQueuePriority(
384	          getQueuePath());
385	
386	      // Update multi-node sorting algorithm for scheduling as configured.
387	      setMultiNodeSortingPolicyName(
388	          configuration.getMultiNodesSortingAlgorithmPolicy(getQueuePath()));
389	
390	      // Setup application related limits
391	      this.queueAppLifetimeSettings = new QueueAppLifetimeAndLimitSettings(configuration,
392	          this, getQueuePath());
393	    } finally {
394	      writeLock.unlock();
395	    }
396	  }
