80	  public static ValidationResult validateQueuePathAutoCreation(
81	      CapacitySchedulerQueueManager queueManager, String path) {
82	    //Some sanity checks, the empty path and existing queue can be checked easy
83	    if (path == null || path.isEmpty()) {
84	      return ValidationResult.EMPTY_PATH;
85	    }
86	
87	    if (queueManager.getQueue(path) != null) {
88	      return ValidationResult.QUEUE_EXISTS;
89	    }
90	
91	    if (queueManager.isAmbiguous(path)) {
92	      return ValidationResult.AMBIGUOUS_QUEUE;
93	    }
94	
95	    //Creating the path of the parent queue and grand parent queue
96	    ArrayList<String> parts = new ArrayList<>();
97	    Collections.addAll(parts, path.split("\\."));
98	
99	    //dropping leaf name part of the path
100	    parts.remove(parts.size() - 1);
101	    String parentPath = parts.size() >= 1 ? String.join(".", parts) : "";
102	    //dropping parent name part of the path
103	    parts.remove(parts.size() - 1);
104	    String grandParentPath = parts.size() >= 1 ? String.join(".", parts) : "";
105	
106	    if (parentPath.isEmpty()) {
107	      return ValidationResult.NO_PARENT_PROVIDED;
108	    }
109	
110	    if (queueManager.isAmbiguous(parentPath)) {
111	      return ValidationResult.AMBIGUOUS_PARENT;
112	    }
113	    CSQueue parentQueue = queueManager.getQueue(parentPath);
114	    if (parentQueue == null) {
115	      if (grandParentPath.isEmpty()) {
116	        return ValidationResult.NO_PARENT_PROVIDED;
117	      }
118	
119	      if (queueManager.isAmbiguous(grandParentPath)) {
120	        return ValidationResult.AMBIGUOUS_PARENT;
121	      }
122	      //if we don't have a valid parent queue, we need to check the grandparent
123	      //if the grandparent allows new dynamic creation, the dynamic parent and
124	      //the dynamic leaf queue can be created as well

