27	public class TestQueuePath {
28	  private static final String TEST_QUEUE = "root.level_1.level_2.level_3";
29	
30	  @Test
31	  public void testCreation() {
32	    QueuePath queuePath = new QueuePath(TEST_QUEUE);
33	
34	    Assert.assertEquals(TEST_QUEUE, queuePath.getFullPath());
35	    Assert.assertEquals("root.level_1.level_2", queuePath.getParent());
36	    Assert.assertEquals("level_3", queuePath.getLeafName());
37	
38	    QueuePath rootPath = new QueuePath(CapacitySchedulerConfiguration.ROOT);
39	    Assert.assertNull(rootPath.getParent());
40	
41	    QueuePath appendedPath = queuePath.createNewLeaf("level_4");
42	    Assert.assertEquals(TEST_QUEUE + CapacitySchedulerConfiguration.DOT
43	        + "level_4", appendedPath.getFullPath());
44	    Assert.assertEquals("root.level_1.level_2.level_3", appendedPath.getParent());
45	    Assert.assertEquals("level_4", appendedPath.getLeafName());
46	  }
47	
48	  @Test
49	  public void testEmptyPart() {
50	    QueuePath queuePathWithEmptyPart = new QueuePath("root..level_2");
51	    QueuePath queuePathWithoutEmptyPart = new QueuePath(TEST_QUEUE);
52	
53	    Assert.assertTrue(queuePathWithEmptyPart.hasEmptyPart());
54	    Assert.assertFalse(queuePathWithoutEmptyPart.hasEmptyPart());
55	  }
56	
57	  @Test
58	  public void testIterator() {
59	    QueuePath queuePath = new QueuePath(TEST_QUEUE);
60	    QueuePath queuePathWithEmptyPart = new QueuePath("root..level_2");
61	    QueuePath rootPath = new QueuePath(CapacitySchedulerConfiguration.ROOT);
62	
63	    List<String> queuePathCollection = ImmutableList.copyOf(queuePath.iterator());
64	    List<String> queuePathWithEmptyPartCollection = ImmutableList.copyOf(
65	        queuePathWithEmptyPart.iterator());
66	    List<String> rootPathCollection = ImmutableList.copyOf(rootPath.iterator());
67	
68	    Assert.assertEquals(4, queuePathCollection.size());
69	    Assert.assertEquals(CapacitySchedulerConfiguration.ROOT, queuePathCollection.get(0));
70	    Assert.assertEquals("level_3", queuePathCollection.get(3));
71	
72	    Assert.assertEquals(3, queuePathWithEmptyPartCollection.size());
73	    Assert.assertEquals(CapacitySchedulerConfiguration.ROOT,
74	        queuePathWithEmptyPartCollection.get(0));
75	    Assert.assertEquals("level_2", queuePathWithEmptyPartCollection.get(2));
76	
77	    Assert.assertEquals(1, rootPathCollection.size());
78	    Assert.assertEquals(CapacitySchedulerConfiguration.ROOT, rootPathCollection.get(0));
79	  }
80	
81	  @Test
82	  public void testReversePathIterator() {
83	    QueuePath queuePath = new QueuePath(TEST_QUEUE);
84	    QueuePath queuePathWithEmptyPart = new QueuePath("root..level_2");
85	    QueuePath rootPath = new QueuePath(CapacitySchedulerConfiguration.ROOT);
86	
87	    List<String> queuePathCollection = ImmutableList.copyOf(queuePath.reverseIterator());
88	    List<String> queuePathWithEmptyPartCollection = ImmutableList.copyOf(
89	        queuePathWithEmptyPart.reverseIterator());
90	    List<String> rootPathCollection = ImmutableList.copyOf(rootPath.reverseIterator());
91	
92	    Assert.assertEquals(4, queuePathCollection.size());
93	    Assert.assertEquals(CapacitySchedulerConfiguration.ROOT,
94	        queuePathCollection.get(3));
95	    Assert.assertEquals(TEST_QUEUE, queuePathCollection.get(0));
96	
97	    Assert.assertEquals(3, queuePathWithEmptyPartCollection.size());
98	    Assert.assertEquals(CapacitySchedulerConfiguration.ROOT,
99	        queuePathWithEmptyPartCollection.get(2));
100	    Assert.assertEquals("root..level_2", queuePathWithEmptyPartCollection.get(0));
101	
102	    Assert.assertEquals(1, rootPathCollection.size());
103	    Assert.assertEquals(CapacitySchedulerConfiguration.ROOT,
104	        rootPathCollection.get(0));
105	  }
106	
107	  @Test
108	  public void testEquals() {
109	    QueuePath queuePath = new QueuePath(TEST_QUEUE);
110	    QueuePath queuePathSame = new QueuePath(TEST_QUEUE);
111	
112	    QueuePath empty = new QueuePath("");
113	    QueuePath emptySame = new QueuePath("");
114	
115	    Assert.assertEquals(queuePath, queuePathSame);
116	    Assert.assertEquals(empty, emptySame);
117	    Assert.assertNotEquals(null, queuePath);
118	  }
